mapper.select:
        select
        *
        from
        wms_material_freeze
        where
        bool_delete_enum = 0
        
            and find_in_set(#{freezeType},total_freeze_types)
        
        
            and material_is_whole = #{materialIsWhole}
        
        
            and workshop_id = #{workshopId}
        
        
            and warehouse_id = #{warehouseId}
        
        
            and warehouse_type = #{projectWarehouseType}
        
        
            and project_id = #{projectId}
        
        
            and theory_thickness = #{theoryThickness}
        
        
            and thickness = #{thickness}
        
        
            and basic_class = #{ basicClass}
        
        
            and width = #{width}
        
        
            and length = #{length}
        

        
            and steel_coil_length >= #{minLength}
        
        
            and steel_coil_length <= #{maxLength}
        

        
            and color like CONCAT('%', #{color},'%')
        
        
            and specification like CONCAT('%', #{specification},'%')
        
        
            and heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            and classify_id in
            
                #{item}
            
        
        
            and classify_id = #{classifyId}
